expected_einlang:
let @e[i] = exp(x[i]) * @x[i];
let @s = sum[k](@e[k]);
let @y[i] = (s * @e[i] - e[i] * @s) / s ** 2.0;

let @y = {
    let _@sinh_x: f32 = {
        let ax = abs(x);
        let _@ax = { sign(x) * @x };
        if ax < 20.0 { 0.5 * ({ exp(x) * @x } - { exp(-x) * -@x }) } else {
        let s = if x as f32 >= 0.0 { 1.0 } else { -1.0 };
        let _@s = if x as f32 >= 0.0 { 0.0 } else { 0.0 };
        s * 0.5 * { exp(ax) * _@ax } + exp(ax) * 0.5 * _@s
    }
    };
    _@sinh_x
};

let @y = {
    let _@cosh_x: f32 = {
        let ax = abs(x);
        let _@ax = { sign(x) * @x };
        if ax < 20.0 { 0.5 * ({ exp(x) * @x } + { exp(-x) * -@x }) } else { 0.5 * { exp(ax) * _@ax } }
    };
    _@cosh_x
};

let @y = {
    let _@sign_x: f32 = if x as f32 > 0.0 { 0.0 } else if x as f32 < 0.0 { 0.0 } else { 0.0 };
    _@sign_x
};

let @y = {
    let _@min_call: f32 = if x < 5.0 { @x } else { 0.0 };
    _@min_call
};

let @y = {
    let _@max_call: f32 = if x > 0.0 { @x } else { 0.0 };
    _@max_call
};

let @y = {
    let _@reduce_l1_x: [f32; *] = {
        let _@result[batch.0] = sum[j]({ sign(x[batch.0, j]) * @x[batch.0, j] });
        _@result
    };
    _@reduce_l1_x
};

let @y = {
    let _@reduce_sum_square_x: [f32; *] = {
        let _@result[batch.0] = sum[j](2.0 * x[batch.0, j] * @x[batch.0, j]);
        _@result
    };
    _@reduce_sum_square_x
};

let @y = {
    let count = len(x[0]) as f32;
    let _@sum_val[batch.0] = sum[j](@x[batch.0, j]);
    let _@mean[batch.0] = _@sum_val[batch.0] / count;
    _@mean
};

let @y = {
    let _@linear_call: [f32; ?, ?] = {
        let _@output[batch.0, j] = sum[k](x[batch.0, k] * @W[j, k] + W[j, k] * @x[batch.0, k]) + @b[j];
        _@output
    };
    _@linear_call
};

let @y = {
    let _@mse_loss_call: [f32; ?] = {
        let n = len(pred[0]) as f32;
        let _@loss[batch.0] = sum[j](2.0 * (pred[batch.0, j] - target[batch.0, j]) * (@pred[batch.0, j] - @target[batch.0, j])) / n;
        _@loss
    };
    _@mse_loss_call
};

let @y = {
    let _@mae_loss_call: [f32; ?] = {
        let n = len(pred[0]) as f32;
        let _@loss[batch.0] = sum[j]({ sign(pred[batch.0, j] - target[batch.0, j]) * (@pred[batch.0, j] - @target[batch.0, j]) }) / n;
        _@loss
    };
    _@mae_loss_call
};

let @y = {
    let _@huber_loss_call: [f32; ?] = {
        let n = len(pred[0]) as f32;
        let diff[batch.0, j] = pred[batch.0, j] - target[batch.0, j];
        let abs_diff[batch.0, j] = abs(diff[batch.0, j]);
        let _@diff[batch.0, j] = @pred[batch.0, j] - @target[batch.0, j];
        let _@abs_diff[batch.0, j] = sign(diff[batch.0, j]) * _@diff[batch.0, j];
        let _@huber_elem[batch.0, j] = if abs_diff[batch.0, j] <= 1.0 { 0.5 * diff[batch.0, j] * _@diff[batch.0, j] + diff[batch.0, j] * 0.5 * _@diff[batch.0, j] } else { _@abs_diff[batch.0, j] };
        let _@loss[batch.0] = sum[j](_@huber_elem[batch.0, j]) / n;
        _@loss
    };
    _@huber_loss_call
};

let @y = {
    let _@binary_cross_entropy_call: [f32; ?] = {
        let eps = 1e-07;
        let clipped_pred[batch.0, j] = if pred[batch.0, j] < eps { eps } else if pred[batch.0, j] > 1.0 - eps { 1.0 - eps } else { pred[batch.0, j] };
        let _@clipped_pred[batch.0, j] = if pred[batch.0, j] < eps { 0.0 } else if pred[batch.0, j] > 1.0 - eps { 0.0 } else { @pred[batch.0, j] };
        let _@loss[batch.0] = -sum[j](target[batch.0, j] * { 1.0 / clipped_pred[batch.0, j] * _@clipped_pred[batch.0, j] } + ln(clipped_pred[batch.0, j]) * @target[batch.0, j] + (1.0 - target[batch.0, j]) * { 1.0 / (1.0 - clipped_pred[batch.0, j]) * (0.0 - _@clipped_pred[batch.0, j]) } + ln(1.0 - clipped_pred[batch.0, j]) * (0.0 - @target[batch.0, j]));
        _@loss
    };
    _@binary_cross_entropy_call
};

let @y = {
    let max_val[batch.0] = max[j](x[batch.0, j]);
    let shifted[batch.0, j] = x[batch.0, j] - max_val[batch.0];
    let exp_vals[batch.0, j] = exp(shifted[batch.0, j]);
    let sums[batch.0] = sum[k](exp_vals[batch.0, k]);
    let _@max_val[batch.0] = @x[batch.0, j] at argmax[j](x[batch.0, j]);
    let _@shifted[batch.0, j] = @x[batch.0, j] - _@max_val[batch.0];
    let _@exp_vals[batch.0, j] = exp(shifted[batch.0, j]) * _@shifted[batch.0, j];
    let _@sums[batch.0] = sum[k](_@exp_vals[batch.0, k]);
    let _@output[batch.0, j] = (sums[batch.0] * _@exp_vals[batch.0, j] - exp_vals[batch.0, j] * _@sums[batch.0]) / sums[batch.0] ** 2.0;
    _@output
};

let @y = {
    let max_val[batch.0] = max[j](x[batch.0, j]);
    let shifted[batch.0, j] = x[batch.0, j] - max_val[batch.0];
    let exp_vals[batch.0, j] = exp(shifted[batch.0, j]);
    let sum_exp[batch.0] = sum[k](exp_vals[batch.0, k]);
    let _@max_val[batch.0] = @x[batch.0, j] at argmax[j](x[batch.0, j]);
    let _@shifted[batch.0, j] = @x[batch.0, j] - _@max_val[batch.0];
    let _@exp_vals[batch.0, j] = exp(shifted[batch.0, j]) * _@shifted[batch.0, j];
    let _@sum_exp[batch.0] = sum[k](_@exp_vals[batch.0, k]);
    let _@log_sum[batch.0] = { 1.0 / sum_exp[batch.0] * _@sum_exp[batch.0] } + _@max_val[batch.0];
    let _@output[batch.0, j] = @x[batch.0, j] - _@log_sum[batch.0];
    _@output
};

let @y = {
    let sum_squares[batch.0] = sum[j](x[batch.0, j] ** 2.0);
    let _@sum_squares[batch.0] = sum[j](2.0 * x[batch.0, j] * @x[batch.0, j]);
    let _@result[batch.0] = 0.5 * sum_squares[batch.0] ** -0.5 * _@sum_squares[batch.0];
    _@result
};

let @y = {
    let sum_val[batch.0] = sum[j](x[batch.0, j]);
    let _@sum_val[batch.0] = sum[j](@x[batch.0, j]);
    let _@result[batch.0] = 1.0 / sum_val[batch.0] * _@sum_val[batch.0];
    _@result
};

let @y = {
    let max_val[batch.0] = max[j](x[batch.0, j]);
    let shifted[batch.0, j] = x[batch.0, j] - max_val[batch.0];
    let sum_exp[batch.0] = sum[j](exp(shifted[batch.0, j]));
    let _@max_val[batch.0] = @x[batch.0, j] at argmax[j](x[batch.0, j]);
    let _@shifted[batch.0, j] = @x[batch.0, j] - _@max_val[batch.0];
    let _@sum_exp[batch.0] = sum[j]({ exp(shifted[batch.0, j]) * _@shifted[batch.0, j] });
    let _@result[batch.0] = _@max_val[batch.0] + { 1.0 / sum_exp[batch.0] * _@sum_exp[batch.0] };
    _@result
};

let @y = {
    let _@cosine_similarity_call: [f32; ?] = {
        let dot_product[batch.0] = sum[j](a[batch.0, j] * b[batch.0, j]);
        let norm_a_sq[batch.0] = sum[j](a[batch.0, j] * a[batch.0, j]);
        let norm_b_sq[batch.0] = sum[j](b[batch.0, j] * b[batch.0, j]);
        let norm_a[batch.0] = sqrt(norm_a_sq[batch.0]);
        let norm_b[batch.0] = sqrt(norm_b_sq[batch.0]);
        let _@dot_product[batch.0] = sum[j](a[batch.0, j] * @b[batch.0, j] + b[batch.0, j] * @a[batch.0, j]);
        let _@norm_a_sq[batch.0] = sum[j](2.0 * a[batch.0, j] * @a[batch.0, j]);
        let _@norm_b_sq[batch.0] = sum[j](2.0 * b[batch.0, j] * @b[batch.0, j]);
        let _@norm_a[batch.0] = 0.5 * norm_a_sq[batch.0] ** -0.5 * _@norm_a_sq[batch.0];
        let _@norm_b[batch.0] = 0.5 * norm_b_sq[batch.0] ** -0.5 * _@norm_b_sq[batch.0];
        let _@similarity[batch.0] = (norm_a[batch.0] * norm_b[batch.0] * _@dot_product[batch.0] - dot_product[batch.0] * (norm_a[batch.0] * _@norm_b[batch.0] + norm_b[batch.0] * _@norm_a[batch.0])) / (norm_a[batch.0] * norm_b[batch.0]) ** 2.0;
        _@similarity
    };
    _@cosine_similarity_call
};

let @C = {
    let _@matmul_call: [f32; ?, ?] = {
        let _@output[i, j] = sum[k](A[i, k] * @B[k, j] + B[k, j] * @A[i, k]);
        _@output
    };
    _@matmul_call
};

let @C = {
    let _@batch_matmul_call: [f32; ?, ?, ?] = {
        let _@result[batch.0, i, j] = sum[k](A[batch.0, i, k] * @B[batch.0, k, j] + B[batch.0, k, j] * @A[batch.0, i, k]);
        _@result
    };
    _@batch_matmul_call
};

let @y = {
    let _@relu_x: f32 = if x > 0.0 { @x } else { 0.0 };
    _@relu_x
};

let @y = {
    let _@leaky_relu_call: f32 = if x > 0 { @x } else { 0.01 * @x };
    _@leaky_relu_call
};

let @y = {
    let _@elu_call: f32 = if x > 0 { @x } else { { exp(x) * @x } };
    _@elu_call
};

let @y = {
    let _@hardtanh_call: f32 = if x < -1.0 { 0.0 } else if x > 1.0 { 0.0 } else { @x };
    _@hardtanh_call
};

let @y = {
    let _@relu6_x: f32 = if x <= 0.0 { 0.0 } else if x >= 6.0 { 0.0 } else { @x };
    _@relu6_x
};

let @y = {
    let _@prelu_call: f32 = if x > 0.0 { @x } else { 0.1 * @x };
    _@prelu_call
};

let @y = {
    let _@elu_alpha_call: f32 = if x > 0.0 { @x } else { 0.5 * { exp(x) * @x } };
    _@elu_alpha_call
};

let @y = {
    let _@celu_call: f32 = if x > 0.0 { @x } else { { exp(x / 1.0) * @x / 1.0 ** 2.0 } };
    _@celu_call
};

let @y = {
    let _@softshrink_call: f32 = if x > 0.5 { @x } else if x < -0.5 { @x } else { 0.0 };
    _@softshrink_call
};

let @y = {
    let _@hardshrink_call: f32 = {
        let abs_x = if x < 0.0 { -x } else { x };
        let _@abs_x = if x < 0.0 { -@x } else { @x };
        if abs_x > 0.5 { @x } else { 0.0 }
    };
    _@hardshrink_call
};

let @y = {
    let _@threshold_call: f32 = if x <= 0.5 { 0.0 } else { @x };
    _@threshold_call
};

let @y = {
    let _@hardswish_x: f32 = (x * if x + 3.0 <= 0.0 { 0.0 } else if x + 3.0 >= 6.0 { 0.0 } else { @x } + relu6(x + 3.0) * @x) / 6.0;
    _@hardswish_x
};

let @y = {
    let _@thresholded_relu_call: f32 = if x > 0.5 { @x } else { 0.0 };
    _@thresholded_relu_call
};

let @y = {
    let lambda = 1.0507009873554805;
    let alpha = 1.6732632423543772;
    if x > 0 { lambda * @x } else { lambda * alpha * { exp(x) * @x } }
};

let @y = {
    let shifted = x + 3.0;
    let _@shifted = @x;
    let _@clamped = if shifted < 0.0 { 0.0 } else if shifted > 6.0 { 0.0 } else { _@shifted };
    _@clamped / 6.0
};

let @y = {
    let _@softplus_x: f32 = if x > 20.0 { @x } else { { 1.0 / (1.0 + exp(x)) * { exp(x) * @x } } };
    _@softplus_x
};

let @y = {
    let sqrt_2_over_pi = 0.7978845608028654;
    let coeff = 0.044715;
    let inner = sqrt_2_over_pi * (x + coeff * x * x * x);
    let _@inner = sqrt_2_over_pi * (@x + coeff * (x * x * @x + x * 2.0 * x * @x));
    0.5 * x * if inner as f32 >= 0.0 {
    let t = exp(-2.0 * inner);
    let _@t = { exp(-2.0 * inner) * -2.0 * _@inner };
    ((1.0 + t) * (0.0 - _@t) - (1.0 - t) * _@t) / (1.0 + t) ** 2.0
} else {
    let t = exp(2.0 * inner);
    let _@t = { exp(2.0 * inner) * 2.0 * _@inner };
    ((t + 1.0) * _@t - (t - 1.0) * _@t) / (t + 1.0) ** 2.0
} + (1.0 + tanh(inner)) * 0.5 * @x
};
